import axios from 'axios';
import AppLayout from './AppLayout.vue';
export default {
  name: 'PasswordResetRequests',
  components: {
    AppLayout
  },
  data() {
    return {
      requests: [],
      selectedRequest: null,
      loading: false,
      filters: {
        status: '',
        search: ''
      },
      stats: {
        pending: 0,
        approved: 0,
        rejected: 0,
        completed: 0
      },
      searchTimeout: null,
      // Pagination
      currentPage: 1,
      itemsPerPage: 10,
      // Modal states
      showApproveModal: false,
      showRejectModal: false,
      showResetModal: false,
      showSuccessModal: false,
      actionRequest: null,
      rejectReason: '',
      resetPasswordData: null,
      successMessage: ''
    };
  },
  created() {
    this.loadRequests();
  },
  computed: {
    paginatedRequests() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.requests.slice(start, end);
    },
    totalPages() {
      return Math.ceil(this.requests.length / this.itemsPerPage);
    },
    showingFrom() {
      return this.requests.length === 0 ? 0 : (this.currentPage - 1) * this.itemsPerPage + 1;
    },
    showingTo() {
      const to = this.currentPage * this.itemsPerPage;
      return to > this.requests.length ? this.requests.length : to;
    }
  },
  methods: {
    async loadRequests() {
      this.loading = true;
      try {
        const params = {};
        if (this.filters.status) params.status = this.filters.status;
        if (this.filters.search) params.search = this.filters.search;
        const response = await axios.get(`${process.env.VUE_APP_API_URL}/password-reset-requests/`, {
          params,
          headers: {
            Authorization: `Bearer ${localStorage.getItem('access_token')}`
          }
        });
        if (Array.isArray(response.data)) {
          this.requests = response.data;
        } else if (response.data && Array.isArray(response.data.results)) {
          this.requests = response.data.results;
        } else {
          this.requests = [];
        }
        this.calculateStats();
        this.currentPage = 1; // Reset to first page on new data
      } catch (error) {
        console.error('Error loading requests:', error);
        this.requests = [];
        this.calculateStats();
        alert('Failed to load password reset requests. Please try again.');
      } finally {
        this.loading = false;
      }
    },
    calculateStats() {
      if (!Array.isArray(this.requests)) {
        this.stats = {
          pending: 0,
          approved: 0,
          rejected: 0,
          completed: 0
        };
        return;
      }
      this.stats = {
        pending: this.requests.filter(r => r.status === 'PENDING').length,
        approved: this.requests.filter(r => r.status === 'APPROVED').length,
        rejected: this.requests.filter(r => r.status === 'REJECTED').length,
        completed: this.requests.filter(r => r.status === 'COMPLETED').length
      };
    },
    debounceSearch() {
      clearTimeout(this.searchTimeout);
      this.searchTimeout = setTimeout(() => {
        this.loadRequests();
      }, 500);
    },
    changeItemsPerPage() {
      this.currentPage = 1; // Reset to first page when changing items per page
    },
    goToPage(page) {
      if (page >= 1 && page <= this.totalPages) {
        this.currentPage = page;
      }
    },
    previousPage() {
      if (this.currentPage > 1) {
        this.currentPage--;
      }
    },
    nextPage() {
      if (this.currentPage < this.totalPages) {
        this.currentPage++;
      }
    },
    viewRequest(request) {
      this.selectedRequest = request;
    },
    // Modal handlers
    openApproveModal(request) {
      this.actionRequest = request;
      this.showApproveModal = true;
    },
    openRejectModal(request) {
      this.actionRequest = request;
      this.rejectReason = '';
      this.showRejectModal = true;
    },
    openResetModal(request) {
      this.actionRequest = request;
      this.showResetModal = true;
    },
    closeModals() {
      this.showApproveModal = false;
      this.showRejectModal = false;
      this.showResetModal = false;
      this.showSuccessModal = false;
      this.actionRequest = null;
      this.rejectReason = '';
      this.resetPasswordData = null;
      this.successMessage = '';
    },
    showSuccess(message) {
      this.successMessage = message;
      this.showSuccessModal = true;
    },
    async approveRequest() {
      if (!this.actionRequest) return;
      try {
        console.log('Approving request:', this.actionRequest.id);
        const response = await axios.patch(`${process.env.VUE_APP_API_URL}/password-reset-requests/${this.actionRequest.id}/`, {
          status: 'APPROVED'
        }, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('access_token')}`
          }
        });
        console.log('Approve response:', response.data);
        this.closeModals();
        this.showSuccess('Request approved successfully. You can now reset the password.');
        this.selectedRequest = null;
        this.loadRequests();
      } catch (error) {
        console.error('Error approving request:', error);
        console.error('Error response:', error.response?.data);
        alert(`Failed to approve request: ${error.response?.data?.detail || error.message}`);
      }
    },
    async resetPassword() {
      if (!this.actionRequest) return;
      try {
        console.log('Resetting password for:', this.actionRequest.username);
        const response = await axios.post(`${process.env.VUE_APP_API_URL}/auth/reset_user_password/`, {
          username: this.actionRequest.username,
          request_id: this.actionRequest.id
        }, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('access_token')}`
          }
        });
        console.log('Reset password response:', response.data);
        this.resetPasswordData = response.data;

        // Keep modal open to show the password
      } catch (error) {
        console.error('Error resetting password:', error);
        console.error('Error response:', error.response?.data);
        alert(`Failed to reset password: ${error.response?.data?.error || error.message}`);
      }
    },
    closeResetModal() {
      this.closeModals();
      this.selectedRequest = null;
      this.loadRequests();
    },
    copyPassword() {
      if (this.resetPasswordData && this.resetPasswordData.new_password) {
        // Try modern clipboard API first
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(this.resetPasswordData.new_password).then(() => {
            this.showSuccess('Password copied to clipboard!');
          }).catch(err => {
            console.error('Clipboard API failed:', err);
            // Fallback to textarea method
            this.copyPasswordFallback();
          });
        } else {
          // Fallback for older browsers
          this.copyPasswordFallback();
        }
      }
    },
    copyPasswordFallback() {
      try {
        // Create temporary textarea
        const textarea = document.createElement('textarea');
        textarea.value = this.resetPasswordData.new_password;
        textarea.style.position = 'fixed';
        textarea.style.opacity = '0';
        document.body.appendChild(textarea);
        textarea.focus();
        textarea.select();

        // Try to copy
        const successful = document.execCommand('copy');
        document.body.removeChild(textarea);
        if (successful) {
          this.showSuccess('Password copied to clipboard!');
        } else {
          alert('Failed to copy password. Please copy it manually.');
        }
      } catch (err) {
        console.error('Fallback copy failed:', err);
        alert('Failed to copy password. Please copy it manually.');
      }
    },
    async rejectRequest() {
      if (!this.actionRequest) return;
      try {
        console.log('Rejecting request:', this.actionRequest.id);
        const response = await axios.patch(`${process.env.VUE_APP_API_URL}/password-reset-requests/${this.actionRequest.id}/`, {
          status: 'REJECTED',
          admin_notes: this.rejectReason || 'Request rejected'
        }, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('access_token')}`
          }
        });
        console.log('Reject response:', response.data);
        this.closeModals();
        this.showSuccess('Request rejected successfully.');
        this.selectedRequest = null;
        this.loadRequests();
      } catch (error) {
        console.error('Error rejecting request:', error);
        console.error('Error response:', error.response?.data);
        alert(`Failed to reject request: ${error.response?.data?.detail || error.message}`);
      }
    },
    getStatusClass(status) {
      if (!status) return 'status-unknown';
      const statusMap = {
        'PENDING': 'status-pending',
        'APPROVED': 'status-approved',
        'REJECTED': 'status-rejected',
        'COMPLETED': 'status-completed'
      };
      return statusMap[status] || 'status-unknown';
    },
    formatDate(dateString) {
      if (!dateString) return 'N/A';
      const date = new Date(dateString);
      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric'
      });
    },
    formatDateTime(dateString) {
      if (!dateString) return 'N/A';
      const date = new Date(dateString);
      return date.toLocaleString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    }
  }
};
